// Generated by Cypress Author on 2026-10-22
//
// REL 04 (P1) — Plano_de_Testes_QA_MatchWallet.md §8 (docs-test/areas/rel.md).
// O servidor limita `POST /relatorios/gerar` a 10 por minuto, contado por ADMIN (o `getTracker`
// usa o id do usuário do token; o contador entra antes da validação do corpo, então requisição
// inválida também gasta cota). Este teste consome a cota inteira de propósito: mantenha-o em spec
// próprio e fora de execução paralela com outros que gerem relatório.
//
// Escopo confirmado pelo código: por usuário, não por carteira nem global. O segundo administrador
// é uma conta descartável promovida e rebaixada de volta pelo admin real.

import { competenciaRelativa } from '../../support/commands/fluxos'

const LIMITE = 10
const JANELA_SEGUNDOS = 60

let carteiraId = ''
let segundoAdminId = ''

function comoAdmin() {
  cy.clearCookies()
  cy.loginReal('admin')
}

function gerar(extras: Record<string, unknown> = {}) {
  return cy.apiRequest({
    method: 'POST',
    url: '/relatorios/gerar',
    body: { carteiraId, mesReferencia: competenciaRelativa(), forcar: true, ...extras },
    failOnStatusCode: false,
  })
}

function totalNoAcervo() {
  return cy
    .apiRequest<{ total: number }>({
      method: 'GET',
      url: '/relatorios/meus-relatorios?pageSize=1',
    })
    .its('body.total')
}

describe('Plano QA · Limite de geração de relatórios', () => {
  before(() => {
    comoAdmin()
    cy.criarCarteiraDeTeste().then((id) => {
      carteiraId = id
      cy.publicarVersaoDeTeste(id, competenciaRelativa(), [100])
    })
    // Esvazia a janela: gerações de outros specs poderiam ter gasto parte da cota. A espera é a
    // duração da janela do limitador (`ttl` de 60 s), não um atraso arbitrário.
    cy.wait((JANELA_SEGUNDOS + 1) * 1000, { log: false })
  })

  after(() => {
    comoAdmin()
    cy.desativarCarteira(carteiraId)
    if (segundoAdminId) {
      cy.apiRequest({
        method: 'PATCH',
        url: `/usuarios/${segundoAdminId}`,
        body: { perfil: 'cliente' },
      })
    }
  })

  it('REL 04 · dez gerações no minuto e a 11ª → 10 aceitas, excedente recusado (429), sem arquivo parcial, outro admin livre e recuperação após a janela', () => {
    comoAdmin()

    // Dez gerações seguidas: todas aceitas.
    for (let i = 1; i <= LIMITE; i++) {
      gerar({ comentarioMercado: `Geração ${i}` })
        .its('status', { log: false })
        .should('eq', 201)
    }

    totalNoAcervo().then((antes) => {
      // A 11ª é recusada, com o tempo de espera informado.
      gerar({ comentarioMercado: 'Geração 11' }).then(({ status, headers }) => {
        expect(status).to.eq(429)
        expect(Number(headers['retry-after'] ?? 1), 'Retry-After').to.be.greaterThan(0)
        cy.wrap(Number(headers['retry-after'] ?? JANELA_SEGUNDOS)).as('espera')
      })
      // Nada foi gravado pela tentativa recusada (nenhum relatório parcial).
      totalNoAcervo().should('eq', antes)

      // Outro administrador não é afetado: o limite é por usuário.
      cy.criarUsuarioDescartavel().then((conta) => {
        segundoAdminId = conta.id
        cy.apiRequest({
          method: 'PATCH',
          url: `/usuarios/${conta.id}`,
          body: { perfil: 'admin' },
        })
          .its('status')
          .should('be.within', 200, 204)

        cy.clearCookies()
        cy.loginComo(conta)
        gerar({ comentarioMercado: 'Segundo admin' }).its('status').should('eq', 201)
      })

      // O primeiro continua barrado dentro da janela...
      comoAdmin()
      gerar({ comentarioMercado: 'Ainda dentro da janela' }).its('status').should('eq', 429)

      // ...e volta a gerar depois dela.
      cy.get<number>('@espera').then((espera) => {
        // Espera ditada pelo `Retry-After` do servidor.
        cy.wait((espera + 1) * 1000, { log: false })
      })
      gerar({ comentarioMercado: 'Depois da janela' }).its('status').should('eq', 201)
    })
  })
})
